{'role': 'user', 'content': [{'tool_use_id': 'toolu_01Q6brvqwFec3nc5iQPPzHh2', 'type': 'tool_result', 'content': '     1→/** WebSocket client — auto-reconnect, dispatches to Zustand stores.
     2→ *
     3→ * Per frontend/CLAUDE.md: Components never touch WS directly.
     4→ * This module manages the connection and routes typed messages to stores.
     5→ */
     6→
     7→import type { WSMessage } from "../types";
     8→import type { BridgeStatus } from "../types/bridge";
     9→import { useBridgeStore } from "../stores/bridgeStore";
    10→import { useConsoleStore } from "../stores/consoleStore";
    11→import { mapWSMessageToEntries, resetMapperState } from "../utils/consoleMapper";
    12→import { queryClient } from "./queryClient";
    13→
    14→const WS_URL = `ws://${window.location.hostname}:8000/ws`;
    15→
    16→let ws: WebSocket | null = null;
    17→let reconnectTimer: ReturnType<typeof setTimeout> | null = null;
    18→let backoff = 1000; // ms, doubles on each failure up to 30s
    19→const MAX_BACKOFF = 30000;
    20→
    21→/** Previous bridge status for detecting transitions to "running". */
    22→let prevBridgeStatus: BridgeStatus | null = null;
    23→
    24→function dispatchToConsole(msg: WSMessage): void {
    25→  const entries = mapWSMessageToEntries(msg);
    26→  const { addEntry } = useConsoleStore.getState();
    27→  for (const entry of entries) {
    28→    addEntry(entry);
    29→  }
    30→}
    31→
    32→function dispatch(msg: WSMessage): void {
    33→  switch (msg.type) {
    34→    case "bridge_status": {
    35→      const newStatus = msg.payload.status;
    36→
    37→      // Invalidate network queries when bridge transitions to "running"
    38→      // from any non-running state (including null initial state).
    39→      if (newStatus === "running" && prevBridgeStatus !== "running") {
    40→        queryClient.invalidateQueries({ queryKey: ["network", "route"] });
    41→        queryClient.invalidateQueries({ queryKey: ["network", "interfaces"] });
    42→      }
    43→      prevBridgeStatus = newStatus;
    44→
    45→      useBridgeStore.getState().setBridgeState(msg.payload);
    46→      break;
    47→    }
    48→    case "pioneer_status":
    49→      useBridgeStore
    50→        .getState()
    51→        .setPioneerStatus(
    52→          msg.payload.is_receiving,
    53→          msg.payload.last_message_age_ms,
    54→          msg.payload.bridge_connected,
    55→        );
    56→      break;
    57→  }
    58→  dispatchToConsole(msg);
    59→}
    60→
    61→function onOpen(): void {
    62→  backoff = 1000;
    63→  // Reset mapper diff-detection state so the first messages of the new
    64→  // WS session are treated as fresh — not diffed against pre-disconnect state.
    65→  resetMapperState();
    66→  prevBridgeStatus = null;
    67→  useBridgeStore.getState().setWsConnected(true);
    68→  useConsoleStore.getState().addEntry({
    69→    source: "system",
    70→    severity: "info",
    71→    message: "Connected to backend",
    72→    verbose: false,
    73→  });
    74→}
    75→
    76→function onMessage(event: MessageEvent): void {
    77→  try {
    78→    const msg = JSON.parse(event.data) as WSMessage;
    79→    dispatch(msg);
    80→  } catch {
    81→    // Ignore malformed messages
    82→  }
    83→}
    84→
    85→function onClose(): void {
    86→  ws = null;
    87→  useBridgeStore.getState().setWsConnected(false);
    88→  useConsoleStore.getState().addEntry({
    89→    source: "system",
    90→    severity: "error",
    91→    message: "Backend connection lost",
    92→    verbose: false,
    93→  });
    94→  scheduleReconnect();
    95→}
    96→
    97→function onError(): void {
    98→  ws?.close();
    99→}
   100→
   101→function scheduleReconnect(): void {
   102→  if (reconnectTimer) return;
   103→  reconnectTimer = setTimeout(() => {
   104→    reconnectTimer = null;
   105→    connectWebSocket();
   106→  }, backoff);
   107→  backoff = Math.min(backoff * 2, MAX_BACKOFF);
   108→}
   109→
   110→export function connectWebSocket(): void {
   111→  if (ws) return;
   112→
   113→  try {
   114→    ws = new WebSocket(WS_URL);
   115→    ws.onopen = onOpen;
   116→    ws.onmessage = onMessage;
   117→    ws.onclose = onClose;
   118→    ws.onerror = onError;
   119→  } catch {
   120→    scheduleReconnect();
   121→  }
   122→}
   123→
   124→export function disconnectWebSocket(): void {
   125→  if (reconnectTimer) {
   126→    clearTimeout(reconnectTimer);
   127→    reconnectTimer = null;
   128→  }
   129→  if (ws) {
   130→    ws.onclose = null; // Prevent reconnect
   131→    ws.close();
   132→    ws = null;
   133→  }
